/**
 * 零依赖的语法高亮。只做保守的注释 / 字符串 / 数字 / 关键字着色，
 * 所有内容都先转义，永远不会破坏 HTML 结构。
 */

const KEYWORDS = {
  js: `await async break case catch class const continue debugger default delete do else export extends finally for from function get if import in instanceof let new of return set static super switch this throw try typeof var void while with yield true false null undefined`,
  ts: `abstract any as asserts await async break case catch class const constructor continue declare default delete do else enum export extends false finally for from function get if implements import in infer instanceof interface is keyof let module namespace never new null number object of override private protected public readonly return set static string super switch symbol this throw true try type typeof undefined unique unknown var void while yield`,
  python: `and as assert async await break class continue def del elif else except False finally for from global if import in is lambda None nonlocal not or pass raise return True try while with yield match case`,
  bash: `if then elif else fi for while until do done case esac function in select time coproc return exit local export readonly declare unset shift source alias echo cd pwd set trap`,
  json: `true false null`,
  css: `important media supports keyframes font-face import charset layer container`,
};

const LANGS = {
  js: { line: "//", block: ["/*", "*/"], quotes: ['"', "'", "`"], keywords: "js" },
  ts: { line: "//", block: ["/*", "*/"], quotes: ['"', "'", "`"], keywords: "ts" },
  python: {
    line: "#",
    quotes: ['"', "'"],
    triple: true,
    keywords: "python",
    decorator: true,
  },
  bash: { line: "#", quotes: ['"', "'"], keywords: "bash", variables: true },
  sh: { line: "#", quotes: ['"', "'"], keywords: "bash", variables: true },
  json: { quotes: ['"'], keywords: "json", json: true },
  css: { block: ["/*", "*/"], quotes: ['"', "'"], keywords: "css", css: true },
  html: { markup: true },
  xml: { markup: true },
  plain: {},
};

const ALIASES = {
  javascript: "js",
  jsx: "js",
  mjs: "js",
  cjs: "js",
  typescript: "ts",
  tsx: "ts",
  py: "python",
  shell: "bash",
  zsh: "bash",
  sh: "bash",
  yml: "plain",
  yaml: "plain",
  md: "plain",
  markdown: "plain",
  text: "plain",
  txt: "plain",
  console: "bash",
  svg: "html",
};

const escapeHtml = (s) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

function normalizeLang(lang) {
  const key = String(lang || "").toLowerCase();
  return LANGS[key] ? key : ALIASES[key] && LANGS[ALIASES[key]] ? ALIASES[key] : "plain";
}

function highlight(code, lang) {
  const name = normalizeLang(lang);
  const cfg = LANGS[name] || LANGS.plain;
  const kw = KEYWORDS[cfg.keywords] ? new Set(KEYWORDS[cfg.keywords].split(/\s+/)) : new Set();
  const src = String(code).replace(/\r\n/g, "\n").replace(/\s+$/, "");

  if (cfg.markup) return highlightMarkup(src);

  let out = "";
  let i = 0;

  const span = (cls, text) => `<span class="tok-${cls}">${escapeHtml(text)}</span>`;

  while (i < src.length) {
    // 块注释
    if (cfg.block && src.startsWith(cfg.block[0], i)) {
      const end = src.indexOf(cfg.block[1], i + cfg.block[0].length);
      const stop = end === -1 ? src.length : end + cfg.block[1].length;
      out += span("cmt", src.slice(i, stop));
      i = stop;
      continue;
    }

    // 行注释
    if (cfg.line && src.startsWith(cfg.line, i)) {
      const end = src.indexOf("\n", i);
      const stop = end === -1 ? src.length : end;
      out += span("cmt", src.slice(i, stop));
      i = stop;
      continue;
    }

    // Python 三引号
    if (cfg.triple && (src.startsWith('"""', i) || src.startsWith("'''", i))) {
      const q = src.slice(i, i + 3);
      const end = src.indexOf(q, i + 3);
      const stop = end === -1 ? src.length : end + 3;
      out += span("str", src.slice(i, stop));
      i = stop;
      continue;
    }

    const ch = src[i];

    // 字符串
    if (cfg.quotes && cfg.quotes.includes(ch)) {
      let j = i + 1;
      while (j < src.length) {
        if (src[j] === "\\") {
          j += 2;
          continue;
        }
        if (src[j] === ch) {
          j += 1;
          break;
        }
        if (ch !== "`" && src[j] === "\n") break;
        j += 1;
      }
      const isKey = cfg.json && /^\s*:/.test(src.slice(j));
      out += span(isKey ? "prop" : "str", src.slice(i, j));
      i = j;
      continue;
    }

    // 数字（含十六进制、小数、指数）
    if (/[0-9]/.test(ch) && !/[A-Za-z0-9_$]/.test(src[i - 1] || "")) {
      const m = src.slice(i).match(/^(0[xX][0-9a-fA-F]+|\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)/);
      if (m) {
        out += span("num", m[0]);
        i += m[0].length;
        continue;
      }
    }

    // 标识符 / 关键字
    if (/[A-Za-z_$@]/.test(ch)) {
      const start = i;
      if (ch === "@") i += 1;
      if (/[A-Za-z_$]/.test(src[i] || "")) {
        i += 1;
        while (/[A-Za-z0-9_$-]/.test(src[i] || "")) i += 1;
      }
      const word = src.slice(start, i);
      const next = src.slice(i).match(/^\s*/)[0].length + i;
      const isCall = src[next] === "(";

      if (cfg.variables && ch === "$") {
        out += span("var", word);
      } else if (kw.has(word)) {
        out += span("kw", word);
      } else if (cfg.json && src[next] !== ":" && (word === "true" || word === "false" || word === "null")) {
        out += span("kw", word);
      } else if (cfg.css && src[next] === ":") {
        out += span("prop", word);
      } else if (isCall) {
        out += span("fn", word);
      } else {
        out += escapeHtml(word);
      }
      continue;
    }

    // CSS 十六进制颜色
    if (cfg.css && ch === "#" && /[0-9a-fA-F]{3,8}/.test(src.slice(i + 1))) {
      const m = src.slice(i).match(/^#[0-9a-fA-F]{3,8}/);
      out += span("num", m[0]);
      i += m[0].length;
      continue;
    }

    out += escapeHtml(ch);
    i += 1;
  }

  return out;
}

function highlightMarkup(src) {
  let out = "";
  let i = 0;
  const esc = escapeHtml;

  while (i < src.length) {
    if (src.startsWith("<!--", i)) {
      const end = src.indexOf("-->", i + 4);
      const stop = end === -1 ? src.length : end + 3;
      out += `<span class="tok-cmt">${esc(src.slice(i, stop))}</span>`;
      i = stop;
      continue;
    }

    if (src[i] === "<") {
      const m = src.slice(i).match(/^<\/?[A-Za-z][\w:-]*/);
      if (m) {
        out += `<span class="tok-tag">${esc(m[0])}</span>`;
        i += m[0].length;
        // 属性
        while (i < src.length && src[i] !== ">") {
          const attr = src.slice(i).match(/^[\w:-]+/);
          if (attr) {
            out += `<span class="tok-attr">${esc(attr[0])}</span>`;
            i += attr[0].length;
          } else if (src[i] === '"' || src[i] === "'") {
            const q = src[i];
            let j = i + 1;
            while (j < src.length && src[j] !== q) j += 1;
            j = Math.min(j + 1, src.length);
            out += `<span class="tok-str">${esc(src.slice(i, j))}</span>`;
            i = j;
          } else {
            out += esc(src[i]);
            i += 1;
          }
        }
        if (src[i] === ">") {
          out += '<span class="tok-tag">&gt;</span>';
          i += 1;
        }
        continue;
      }
    }

    out += esc(src[i]);
    i += 1;
  }

  return out;
}

/**
 * 一个小而够用的 Markdown 渲染器。
 * 支持：标题、段落、粗斜体、行内代码、链接、图片、引用、列表（含嵌套/任务列表）、
 * 表格、分隔线、围栏代码块（带高亮）、::: 提示块。
 */

const LIST_RE = /^(\s*)([-*+]|\d+\.)\s+(.*)$/;
const esc = (s) =>
  String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

const CJK = /[\u2e80-\u9fff\uf900-\ufaff\uff00-\uffef\u3000-\u303f]/;

function slugify(text) {
  return String(text)
    .toLowerCase()
    .replace(/<[^>]*>/g, "")
    .replace(/[^\p{L}\p{N}\s-]/gu, "")
    .trim()
    .replace(/\s+/g, "-")
    .replace(/-{2,}/g, "-") || "section";
}

function plainText(md) {
  return String(md)
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, "$1")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/[*_~]{1,3}/g, "")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/^>\s?/gm, "")
    .replace(/\s+/g, " ")
    .trim();
}

function renderInline(text, opts = {}) {
  const codes = [];
  let out = String(text).replace(/`([^`]+)`/g, (_, code) => {
    codes.push(code);
    return `\u0000C${codes.length - 1}\u0000`;
  });

  out = esc(out);

  // 图片
  out = out.replace(/!\[([^\]]*)\]\(([^)\s]+)\)/g, (_, alt, src) => {
    return `<img src="${src}" alt="${alt}" loading="lazy" decoding="async">`;
  });

  // 链接
  out = out.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, label, href) => {
    const external = /^https?:\/\//i.test(href) && !href.startsWith(opts.siteUrl || "\u0000");
    const attrs = external ? ' target="_blank" rel="noopener noreferrer"' : "";
    return `<a href="${href}"${attrs}>${label}</a>`;
  });

  // 加粗 / 斜体 / 删除线
  out = out.replace(/\*\*([^*]+?)\*\*/g, "<strong>$1</strong>");
  out = out.replace(/__([^_]+?)__/g, "<strong>$1</strong>");
  out = out.replace(
    /(^|[\s（(、，。；：！？—])\*([^*\n]+?)\*(?=$|[\s）)、，。；：！？—])/g,
    "$1<em>$2</em>"
  );
  out = out.replace(/~~([^~]+?)~~/g, "<del>$1</del>");

  // 还原行内代码
  out = out.replace(/\u0000C(\d+)\u0000/g, (_, idx) => `<code>${esc(codes[Number(idx)])}</code>`);

  return out;
}

function joinSoft(lines) {
  let out = "";
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;
    if (!out) {
      out = line;
      continue;
    }
    if (/\s$/.test(raw) || CJK.test(out.slice(-1)) || CJK.test(line[0])) out += line;
    else out += " " + line;
  }
  return out;
}

function isBlockStart(line) {
  return (
    /^\s*```/.test(line) ||
    /^\s{0,3}#{1,6}\s+/.test(line) ||
    /^\s*>/.test(line) ||
    /^\s*:::\s*\w+/.test(line) ||
    /^\s*([-*_])\s*(?:\1\s*){2,}$/.test(line) ||
    LIST_RE.test(line)
  );
}

function renderMarkdown(markdown, opts = {}) {
  const lines = String(markdown).replace(/\r\n?/g, "\n").split("\n");
  const headings = [];
  const usedIds = new Map();

  const uniqueId = (raw) => {
    const base = slugify(raw);
    const count = usedIds.get(base) || 0;
    usedIds.set(base, count + 1);
    return count === 0 ? base : `${base}-${count}`;
  };

  const inline = (t) => renderInline(t, opts);

  const parseBlocks = (blockLines, collectHeadings = true) => {
    let i = 0;
    let html = "";

    while (i < blockLines.length) {
      const line = blockLines[i];

      if (!line.trim()) {
        i += 1;
        continue;
      }

      // 围栏代码块
      const fence = line.match(/^\s*```\s*([^\s`]*)/);
      if (fence) {
        const lang = fence[1] || "text";
        const code = [];
        i += 1;
        while (i < blockLines.length && !/^\s*```\s*$/.test(blockLines[i])) {
          code.push(blockLines[i]);
          i += 1;
        }
        i += 1; // 跳过结束围栏
        const source = code.join("\n");
        html += `<div class="code-block" data-lang="${esc(lang)}">
  <div class="code-head"><span class="code-lang">${esc(lang)}</span><button class="code-copy" type="button" aria-label="复制代码">复制</button></div>
  <pre><code class="language-${esc(lang)}">${highlight(source, lang)}</code></pre>
</div>`;
        continue;
      }

      // 标题
      const heading = line.match(/^\s{0,3}(#{1,6})\s+(.*?)\s*#*\s*$/);
      if (heading) {
        const level = heading[1].length;
        const text = heading[2];
        const id = uniqueId(plainText(text));
        if (collectHeadings && (level === 2 || level === 3)) {
          headings.push({ level, text: plainText(text), id });
        }
        html += `<h${level} id="${id}">${inline(text)}<a class="heading-anchor" href="#${id}" aria-hidden="true" tabindex="-1">#</a></h${level}>`;
        i += 1;
        continue;
      }

      // 分隔线
      if (/^\s*([-*_])\s*(?:\1\s*){2,}$/.test(line)) {
        html += "<hr>";
        i += 1;
        continue;
      }

      // ::: 提示块
      const callout = line.match(/^\s*:::\s*(note|tip|warn|danger)\s*(.*)$/i);
      if (callout) {
        const type = callout[1].toLowerCase();
        const title = callout[2].trim();
        const body = [];
        i += 1;
        while (i < blockLines.length && !/^\s*:::\s*$/.test(blockLines[i])) {
          body.push(blockLines[i]);
          i += 1;
        }
        i += 1;
        const labels = { note: "提示", tip: "小技巧", warn: "注意", danger: "警告" };
        html += `<aside class="callout callout-${type}">
  <p class="callout-title">${esc(title || labels[type])}</p>
  <div class="callout-body">${parseBlocks(body, false)}</div>
</aside>`;
        continue;
      }

      // 引用
      if (/^\s*>/.test(line)) {
        const quote = [];
        while (i < blockLines.length && (/^\s*>/.test(blockLines[i]) || !blockLines[i].trim())) {
          if (!blockLines[i].trim()) {
            if (i + 1 < blockLines.length && /^\s*>/.test(blockLines[i + 1])) quote.push("");
            else break;
          } else {
            quote.push(blockLines[i].replace(/^\s*>\s?/, ""));
          }
          i += 1;
        }
        html += `<blockquote>${parseBlocks(quote, false)}</blockquote>`;
        continue;
      }

      // 表格
      if (
        line.includes("|") &&
        i + 1 < blockLines.length &&
        /^\s*\|?\s*:?-{2,}:?\s*(\|\s*:?-{2,}:?\s*)+\|?\s*$/.test(blockLines[i + 1])
      ) {
        const cells = (row) =>
          row
            .trim()
            .replace(/^\|/, "")
            .replace(/\|$/, "")
            .split("|")
            .map((c) => c.trim());
        const aligns = cells(blockLines[i + 1]).map((c) => {
          const left = c.startsWith(":");
          const right = c.endsWith(":");
          if (left && right) return "center";
          if (right) return "right";
          return "left";
        });
        const head = cells(line);
        const bodyRows = [];
        i += 2;
        while (i < blockLines.length && blockLines[i].includes("|") && blockLines[i].trim()) {
          bodyRows.push(cells(blockLines[i]));
          i += 1;
        }
        const th = head
          .map((c, idx) => `<th style="text-align:${aligns[idx] || "left"}">${inline(c)}</th>`)
          .join("");
        const trs = bodyRows
          .map(
            (row) =>
              `<tr>${row
                .map((c, idx) => `<td style="text-align:${aligns[idx] || "left"}">${inline(c)}</td>`)
                .join("")}</tr>`
          )
          .join("");
        html += `<div class="table-wrap"><table><thead><tr>${th}</tr></thead><tbody>${trs}</tbody></table></div>`;
        continue;
      }

      // 列表
      if (LIST_RE.test(line)) {
        const { html: listHtml, next } = parseList(blockLines, i);
        html += listHtml;
        i = next;
        continue;
      }

      // 段落
      const para = [];
      while (i < blockLines.length && blockLines[i].trim() && !isBlockStart(blockLines[i])) {
        para.push(blockLines[i]);
        i += 1;
      }
      const text = joinSoft(para);
      const onlyImage = /^!\[[^\]]*\]\([^)]+\)$/.test(text.trim());
      html += onlyImage ? `<figure>${inline(text)}</figure>` : `<p>${inline(text)}</p>`;
    }

    return html;
  };

  const parseList = (blockLines, start) => {
    let i = start;
    const root = { indent: -1, ordered: false, children: [] };
    const stack = [root];
    let lastItem = null;

    while (i < blockLines.length) {
      const line = blockLines[i];

      if (!line.trim()) {
        const next = blockLines[i + 1];
        if (next === undefined) break;
        const nextIndent = next.match(/^\s*/)[0].length;
        if (!LIST_RE.test(next) && nextIndent === 0) break;
        i += 1;
        continue;
      }

      const m = line.match(LIST_RE);
      if (m) {
        const indent = m[1].length;
        const ordered = /^\d+\./.test(m[2]);

        while (stack.length > 1 && indent < stack[stack.length - 1].indent) stack.pop();

        const top = stack[stack.length - 1];

        if (indent === top.indent && ordered !== top.ordered) {
          // 同级但列表类型变化：另起一个列表
          stack.pop();
          const list = { indent, ordered, children: [], parent: top.parent || null };
          if (top.parent) top.parent.children.push(list);
          else root.children.push(list);
          stack.push(list);
        } else if (indent > top.indent) {
          const list = { indent, ordered, children: [], parent: lastItem || null };
          if (lastItem) lastItem.children.push(list);
          else root.children.push(list);
          stack.push(list);
        } else if (indent === top.indent) {
          // 同级，继续当前列表
        } else {
          break;
        }

        lastItem = { text: [m[3]], children: [] };
        stack[stack.length - 1].children.push(lastItem);
        i += 1;
        continue;
      }

      // 续行
      const indent = line.match(/^\s*/)[0].length;
      if (lastItem && indent > stack[stack.length - 1].indent) {
        lastItem.text.push(line.trim());
        i += 1;
        continue;
      }
      break;
    }

    const renderTree = (node) =>
      node.children
        .map((list) => {
          const tag = list.ordered ? "ol" : "ul";
          const items = list.children
            .map((item) => {
              let text = joinSoft(item.text);
              let checkbox = "";
              const task = text.match(/^\[([ xX])\]\s+(.*)$/);
              if (task) {
                checkbox = `<input type="checkbox" disabled${task[1].toLowerCase() === "x" ? " checked" : ""}> `;
                text = task[2];
              }
              const children = item.children.length ? renderTree(item) : "";
              return `<li>${checkbox}${inline(text)}${children}</li>`;
            })
            .join("");
          return `<${tag}>${items}</${tag}>`;
        })
        .join("");

    return { html: renderTree(root), next: i };
  };

  const html = parseBlocks(lines);
  return { html, headings };
}

export { renderMarkdown, slugify, plainText };
